Before:
```cpp
int
main(int argc, char *argv[])
{
      DWORD crc;
      long charcnt;
      register errors = 0;

      while(--argc > 0)
      {
            errors |= crc32file(*++argv, &crc, &charcnt);
            printf("%08lX %7ld %s\n", crc, charcnt, *argv);
      }
      return(errors != 0);
}
```

After:
```cpp
int
main(int argc, char *argv[])
{
      long charcnt;
      register errors = 0;

      while(--argc > 0)
      {
            // Initialize `crc` at the beginning of each iteration since
            // it should not depend on the value of the previous iteration.
            DWORD crc; 

            errors |= crc32file(*++argv, &crc, &charcnt);
            printf("%08lX %7ld %s\n", crc, charcnt, *argv);
      }
      return(errors != 0);
}
```

bit_nset is used to set bits [start, stop], which the stop position is included, so we should pass `bitstring size - 1` as the stop, or it will potentially overflow. It is ok with the month and dom, because their allocted byte was not fully used, but for dow and hour, they use 8 bits and 24bits, the following statement will write the next byte.

bit_nset(e->hour, 0, (LAST_HOUR-FIRST_HOUR+1));
bit_nset(e->dow, 0, (LAST_DOW-FIRST_DOW+1));

